$ErrorActionPreference='Stop'
$path='E:\boss-R65-CANARY-VERIFY-20261014-GPT6\QA_NODE_TEST_RESULT_GPT6_20261014.txt'
if(!(Test-Path -LiteralPath $path)){throw 'MISSING_VERIFICATION_LOG'}
$lines=@(Get-Content -LiteralPath $path)
foreach($needle in @('not ok 1 - 00 ','not ok 13 - 12 ','not ok 15 - 14 ','✖ 00','✖ 12','✖ 14')){
 for($i=0;$i -lt $lines.Count;$i++){
  if($lines[$i].Contains($needle)){
   Write-Output ('=== FAILURE '+$needle+' AT '+($i+1)+' ===')
   $end=[Math]::Min($lines.Count-1,$i+22)
   for($k=$i;$k -le $end;$k++){Write-Output $lines[$k]}
   break
  }
 }
}
Write-Output ('LOG_LINE_COUNT='+$lines.Count)
